    pos++;
double a = double.Parse(expr.Substring(0, pos));
double b = double.Parse(expr.Substring(pos + 1));
char op = expr[pos];
if (op == '+')
    return a + b;
else if (op == '-')
    return a - b;
else if (op == '*')
    return a * b;
else
    return a / b;

